package com.animextv
import java.io.ByteArrayInputStream
import android.util.Base64
import java.util.zip.GZIPInputStream

// ID mapping from the website's own public anime mapping bundle.
internal object AnimeXTVIds {
    private val ids: Map<Int, Int> by lazy {
        val packed = listOf(
            "",
            "",
            "",
            ""
        ).joinToString("")
        GZIPInputStream(ByteArrayInputStream(Base64.decode(packed, Base64.DEFAULT))).bufferedReader().use { it.readText() }
            .split(',').associate { val p = it.split(':'); p[0].toInt() to p[1].toInt() }
    }
    private val reverse by lazy { ids.entries.groupBy({ it.value }, { it.key }).mapValues { (ani, mal) -> mal.firstOrNull { it == ani } ?: mal.first() } }
    fun fromMal(id: Int): Int? = ids[id]
    fun toMal(id: Int): Int? = reverse[id]
}
